mapper.select:
SELECT m.*,p.product_name,p.supplier_item_code,s.supplier_name
FROM the_full_order.tb_account_inventory_movement m
LEFT JOIN the_full_order.tb_account_ingredient_product ap ON ap.account_ingredient_product_id=m.account_ingredient_product_id AND ap.account_id=m.account_id
LEFT JOIN the_full_order.tb_supplier_ingredient_product p ON p.supplier_product_id=ap.supplier_product_id
LEFT JOIN the_full_order.tb_supplier s ON s.supplier_id=p.supplier_id
WHERE m.account_id=#{account_id}
AND m.account_ingredient_product_id=#{account_ingredient_product_id}
AND m.movement_at>=#{date_from}
AND m.movement_at<DATE_ADD(#{date_to},INTERVAL 1 DAY)
ORDER BY m.movement_at DESC,m.movement_id DESC LIMIT #{limit} OFFSET #{offset}
